steps.code:
# /srv/vault/config/vault.hcl
ui            = true
disable_mlock = true
api_addr      = "https://vault-1.example.internal:8200"
cluster_addr  = "https://vault-1.example.internal:8201"
listener "tcp" {
  address       = "0.0.0.0:8200"
  tls_cert_file = "/vault/tls/tls.crt"
  tls_key_file  = "/vault/tls/tls.key"
}
storage "raft" {
  path    = "/vault/file"
  node_id = "vault-1"
  retry_join {
    leader_api_addr     = "https://vault-2.example.internal:8200"
    leader_ca_cert_file = "/vault/tls/tls.crt"
  }
}

# /etc/vault/agent.hcl  (run: vault agent -config=/etc/vault/agent.hcl)
vault {
  address = "https://vault-1.example.internal:8200"
  ca_cert = "/etc/vault/ca.crt"
}
auto_auth {
  method "approle" {
    config = {
      role_id_file_path   = "/etc/vault/role_id"
      secret_id_file_path = "/etc/vault/secret_id"
    }
  }
}
template {
  contents    = "{{ with secret \"secret/data/myapp/config\" }}DB_PASS={{ .Data.data.db_pass }}{{ end }}"
  destination = "/run/myapp/env"
  perms       = "0640"
}
